// Typed access to the parsed rules (src/content/rules.json, generated by
// scripts/parse-rules.mjs from rules/BtP-Alpha-Rules.md).
import rules from './rules.json';

export interface RuleTable {
  headers: string[];
  rows: string[][];
}

export interface RuleItem {
  name: string;
  html: string;
  text: string;
}

export interface RuleNode {
  id: string;
  title: string;
  titleHtml: string;
  depth: number;
  lvl?: number;
  html?: string;
  fields?: Record<string, string>;
  subtitle?: string;
  tables?: RuleTable[];
  items?: RuleItem[];
  children?: RuleNode[];
}

export const sections = (rules as { sections: RuleNode[] }).sections;
export const rulesSource = (rules as { source: string }).source;

const byId = new Map<string, RuleNode>();
const parentOf = new Map<string, RuleNode>();
(function index(nodes: RuleNode[], parent?: RuleNode) {
  for (const n of nodes) {
    byId.set(n.id, n);
    if (parent) parentOf.set(n.id, parent);
    if (n.children) index(n.children, n);
  }
})(sections);

export function getNode(id: string): RuleNode | undefined {
  return byId.get(id);
}

export function mustNode(id: string): RuleNode {
  const n = byId.get(id);
  if (!n) throw new Error(`Rules section not found: ${id}`);
  return n;
}

export function getParent(id: string): RuleNode | undefined {
  return parentOf.get(id);
}

export function allNodes(): RuleNode[] {
  return [...byId.values()];
}

/** A named lead-in item (`***Name.*** text`) within a section. */
export function getItem(id: string, name: string): RuleItem | undefined {
  return byId.get(id)?.items?.find((i) => i.name === name);
}

/** First table found in the node or its descendants. */
export function firstTable(id: string): RuleTable | undefined {
  const walk = (n: RuleNode): RuleTable | undefined =>
    n.tables?.[0] ?? n.children?.map(walk).find(Boolean);
  const n = byId.get(id);
  return n && walk(n);
}

/** Converts `{VIG}` style tokens to readable text. */
export function tokensToText(s: string): string {
  return s.replace(/\{(VIG|AGI|PER|INT|PRS|AP|SL)\}/g, (_, k) => (k === 'SL' ? 'level' : k));
}

// ---------- Spells & maneuvers ----------

export type SpellGroup = 'Arcana' | 'Evocations';
export type SpellTier = 'Cantrip' | 'Mantra' | 'Arcanum' | 'Evocation';

export interface Spell {
  id: string;
  name: string;
  kind: 'spell';
  group: SpellGroup;
  type: string;
  tier: SpellTier;
  level: number;
  subtitle: string;
  fields: Record<string, string>;
  source?: string;
}

export interface Maneuver {
  id: string;
  name: string;
  kind: 'maneuver';
  type: string;
  level: number;
  subtitle: string;
  fields: Record<string, string>;
  source?: string;
}

export type Castable = Spell | Maneuver;

function levelOf(subtitle: string): number {
  const m = subtitle.match(/(\d+)(st|nd|rd|th)-level/);
  return m ? Number(m[1]) : 0;
}

export const ARCANA_TYPES = ['Fire', 'Ice', 'Mind', 'Bio', 'Scour', 'Arc', 'Blood', 'Moon', 'World', 'Null'];
export const EVOCATION_TYPES = ['Flame', 'Frost', 'Pneuma', 'Soma', 'Mordant', 'Velvet', 'Infernal', 'Lunar', 'Temporal', 'Platinum'];
export const MANEUVER_TYPES = ['Feral', 'Martial', 'Instinctual', 'Tactical', 'Psychological'];

function spellFrom(n: RuleNode, group: SpellGroup, type: string, source?: string): Spell | undefined {
  const sub = n.subtitle ?? '';
  const tier = (['Cantrip', 'Mantra', 'Arcanum', 'Evocation'] as SpellTier[]).find((t) => sub.includes(t));
  if (!tier) return undefined;
  return { id: n.id, name: n.title.replace(/\s*\[.*\]$/, ''), kind: 'spell', group, type, tier, level: levelOf(sub), subtitle: sub, fields: n.fields ?? {}, source };
}

export const spells: Spell[] = [];
export const maneuvers: Maneuver[] = [];

for (const g of getNode('spells')?.children ?? []) {
  if (g.title !== 'Arcana' && g.title !== 'Evocations') continue;
  for (const t of g.children ?? []) {
    for (const s of t.children ?? []) {
      const sp = spellFrom(s, g.title as SpellGroup, t.title);
      if (sp) spells.push(sp);
    }
  }
}
for (const t of getNode('maneuvers')?.children ?? []) {
  for (const m of t.children ?? []) {
    if (!m.subtitle?.includes('Maneuver')) continue;
    maneuvers.push({ id: m.id, name: m.title, kind: 'maneuver', type: t.title, level: levelOf(m.subtitle), subtitle: m.subtitle, fields: m.fields ?? {} });
  }
}
// Spells and maneuvers defined inside class facets (e.g. Rage, Smite).
for (const n of allNodes()) {
  if (!n.id.startsWith('classes/') || !n.subtitle) continue;
  const sub = n.subtitle;
  const cls = getNode(n.id.split('/').slice(0, 2).join('/'))?.title;
  if (sub.includes('Maneuver')) {
    const type = sub.split(' ')[0];
    maneuvers.push({ id: n.id, name: n.title, kind: 'maneuver', type, level: levelOf(sub), subtitle: sub, fields: n.fields ?? {}, source: cls });
  } else {
    const type = sub.split(' ')[0];
    const group: SpellGroup = ARCANA_TYPES.includes(type) ? 'Arcana' : 'Evocations';
    const sp = spellFrom(n, group, type, cls);
    if (sp) spells.push(sp);
  }
}

const castableById = new Map<string, Castable>([...spells, ...maneuvers].map((c) => [c.id, c]));
export function getCastable(id: string): Castable | undefined {
  return castableById.get(id);
}

// ---------- Actions & conditions ----------

export interface ActionDef {
  id: string;
  name: string;
  category: string;
  fields: Record<string, string>;
}

export const basicActions: ActionDef[] = [];
for (const cat of getNode('beyond-the-prism/action-list')?.children ?? []) {
  for (const a of cat.children ?? []) {
    basicActions.push({ id: a.id, name: a.title, category: cat.title.replace(/ Actions$/, ''), fields: a.fields ?? {} });
  }
}

export interface ConditionDef {
  id: string;
  name: string;
  leveled: boolean;
}

export const conditions: ConditionDef[] = (getNode('beyond-the-prism/conditions/condition-list')?.children ?? []).map((c) => ({
  id: c.id,
  name: c.title.replace(/\s+X$/, ''),
  leveled: /\sX$/.test(c.title),
}));

// ---------- Equipment ----------

export interface Weapon {
  name: string;
  group: string;
  dv: string;
  deadlyDv: string;
  damage: string;
  requirements: string;
  properties: string[];
}

export const weapons: Weapon[] = [];
for (const id of ['equipment/weapons/weapons-tables', 'equipment/weapons/weapons-table-cont']) {
  const t = getNode(id)?.tables?.[0];
  if (!t) continue;
  let group = '';
  for (const r of t.rows) {
    if (r.slice(1).every((c) => !c)) {
      group = r[0];
      continue;
    }
    const [name, dv, deadlyDv, damage, requirements, props] = r;
    weapons.push({
      name,
      group,
      dv,
      deadlyDv,
      damage,
      requirements: requirements === '—' ? '' : requirements,
      properties: !props || props === '—' ? [] : props.split(/,\s*(?![^()]*\))/).map((p) => p.trim()),
    });
  }
}

export const weaponProperties: RuleNode[] = getNode('equipment/weapons/weapon-properties')?.children ?? [];

export type ArmorType = 'Light' | 'Medium' | 'Heavy';
export interface ArmorQuality {
  quality: string;
  ac: Record<ArmorType, number>;
}
export const armorQualities: ArmorQuality[] = (firstTable('equipment/armor/armor-quality')?.rows ?? []).map((r) => ({
  quality: r[0],
  ac: { Light: Number(r[1]), Medium: Number(r[2]), Heavy: Number(r[3]) },
}));
export const armorRequirements: Record<ArmorType, number> = Object.fromEntries(
  (firstTable('equipment/armor/armor-requirements')?.rows ?? []).map((r) => [r[0], Number(r[1].replace(/\D/g, '')) || 0]),
) as Record<ArmorType, number>;

/** Unarmored Slashing Vulnerability by Vitality Maximum. */
export function slashingVulnerability(vitalityMax: number): string {
  const rows = firstTable('equipment/armor/slashing-vulnerability')?.rows ?? [];
  if (!rows.length) return '';
  const max = Math.max(...rows.map((r) => Number(r[0])));
  if (vitalityMax > max) return '';
  const row = rows.find((r) => Number(r[0]) === Math.max(1, vitalityMax));
  return row?.[1] ?? '';
}

// ---------- Personal alignment ----------

export function personalAlignment(situations: string, problems: string, people: string): string | undefined {
  const t = firstTable('player-characters/character-creation/alignment/i-respond-to-new');
  return t?.rows.find((r) => r[0] === situations && r[1] === problems && r[2] === people)?.[3];
}
